/* Every visitable Ontario provincial park for the Map tab: name, location,
   what you can do there and its official page, from the owner's
   ontario-parks-visitable.csv (116 parks). guideID links a pin to the park
   in the app's own guide; a park the guide does not cover yet (nil) opens
   its official page instead, and Algonquin opens the guide's Algonquin
   campgrounds. Regenerate this list from the CSV, never edit it by hand. */

import CoreLocation

struct MapPark: Identifiable, Hashable {
    enum Kind: Hashable { case camping, backcountry, roofed, dayUse }

    let slug: String
    let name: String
    let latitude: Double
    let longitude: Double
    let kinds: [Kind]
    let officialURL: String
    let guideID: String?

    var id: String { slug }
    var coordinate: CLLocationCoordinate2D { CLLocationCoordinate2D(latitude: latitude, longitude: longitude) }
    var isAlgonquin: Bool { slug == "algonquin" }

